from __future__ import annotations

import os
from contextlib import contextmanager
from typing import Any, Dict, Generator, List, Optional, Tuple

import structlog

from rasa.builder.telemetry.langfuse_integration.langfuse_compat import (
    is_langfuse_configured,
    with_langfuse,
)

structlogger = structlog.get_logger()
LANGFUSE_SESSION_URL_TEMPLATE_ENV_VAR = "LANGFUSE_SESSION_URL_TEMPLATE"
_TRACE_ID_PLACEHOLDER = "00000000000000000000000000000000"
_trace_url_template: Optional[str] = None


def warm_up_langfuse_trace_url() -> None:
    """Resolve and cache the invariant parts of Langfuse trace URLs."""
    global _trace_url_template

    if _trace_url_template is not None:
        return
    if not is_langfuse_configured():
        return
    try:
        with with_langfuse() as lf:
            if not lf:
                return
            langfuse_client = lf.get_client()
            trace_url = langfuse_client.get_trace_url(trace_id=_TRACE_ID_PLACEHOLDER)
            if trace_url and _TRACE_ID_PLACEHOLDER in trace_url:
                _trace_url_template = trace_url.replace(
                    _TRACE_ID_PLACEHOLDER, "{trace_id}", 1
                )
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.warm_up_trace_url.failed",
            error=repr(e),
        )


def get_current_trace_context(sender_id: Optional[str] = None) -> Dict[str, str]:
    """Return current Langfuse trace context for attaching to events."""
    if not is_langfuse_configured():
        return {}
    try:
        with with_langfuse() as lf:
            if not lf:
                return {}
            langfuse_client = lf.get_client()
            trace_id = langfuse_client.get_current_trace_id()
            if not trace_id:
                return {}

            trace_context: Dict[str, str] = {"langfuse_trace_id": str(trace_id)}

            trace_url: Optional[str]
            if _trace_url_template:
                # Fast path: startup already resolved the host and project ID.
                trace_url = _trace_url_template.format(trace_id=trace_id)
            else:
                try:
                    # Fallback when startup warming failed or was not invoked.
                    trace_url = langfuse_client.get_trace_url(trace_id=trace_id)
                except TypeError:
                    # Compatibility with older SDK versions
                    # Trace ID inferred from active trace context
                    trace_url = langfuse_client.get_trace_url()

            if trace_url:
                trace_context["langfuse_trace_url"] = trace_url

            if sender_id:
                session_template = os.getenv(LANGFUSE_SESSION_URL_TEMPLATE_ENV_VAR)
                if session_template:
                    try:
                        trace_context["langfuse_session_url"] = session_template.format(
                            session_id=sender_id,
                            sender_id=sender_id,
                        )
                    except Exception:
                        pass

            return trace_context
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.get_current_trace_context.failed",
            error=repr(e),
        )
        return {}


def update_current_trace_for_turn(
    *,
    sender_id: Optional[str],
    message_id: Optional[str],
    user_id: Optional[str] = None,
    assistant_id: Optional[str] = None,
    model_id: Optional[str] = None,
    input_channel: Optional[str] = None,
    tags: Optional[List[str]] = None,
    trace_input: Optional[Any] = None,
    trace_output: Optional[Any] = None,
) -> None:
    """Best-effort update of current trace with turn/conversation grouping."""
    if not is_langfuse_configured():
        return
    try:
        with with_langfuse() as lf:
            if not lf:
                return
            langfuse_client = lf.get_client()
            metadata: Dict[str, Any] = {
                "sender_id": sender_id,
                "message_id": message_id,
                "assistant_id": assistant_id,
                "model_id": model_id,
                "input_channel": input_channel,
            }
            langfuse_client.update_current_trace(
                session_id=sender_id,
                user_id=user_id,
                input=trace_input,
                output=trace_output,
                metadata=metadata,
                tags=tags or [],
            )
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.update_current_trace_for_turn.failed",
            error=repr(e),
        )


def update_current_span_metadata(
    *,
    name: Optional[str] = None,
    metadata: Optional[Dict[str, Any]] = None,
    span_input: Optional[Any] = None,
    span_output: Optional[Any] = None,
) -> None:
    """Best-effort update of current observation/span metadata."""
    if not is_langfuse_configured():
        return
    try:
        with with_langfuse() as lf:
            if not lf:
                return
            langfuse_client = lf.get_client()
            kwargs: Dict[str, Any] = {}
            if name:
                kwargs["name"] = name
            if metadata:
                kwargs["metadata"] = metadata
            if span_input is not None:
                kwargs["input"] = span_input
            if span_output is not None:
                kwargs["output"] = span_output
            if kwargs:
                langfuse_client.update_current_span(**kwargs)
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.update_current_span_metadata.failed",
            error=repr(e),
        )


class LangfuseSpanHandle:
    """Handle yielded by :func:`langfuse_span` for recording span I/O.

    ``update`` targets the current observation — the span opened by the
    enclosing :func:`langfuse_span` block — so call it inside the ``with`` body
    to attach the span's output (or extra metadata/name). It is best-effort and
    a no-op when Langfuse is unavailable.
    """

    def update(
        self,
        *,
        name: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        output: Optional[Any] = None,
    ) -> None:
        """Record name/metadata/output on the current span (best-effort)."""
        update_current_span_metadata(name=name, metadata=metadata, span_output=output)


@contextmanager
def langfuse_span(
    *,
    name: str,
    metadata: Optional[Dict[str, Any]] = None,
    span_input: Optional[Any] = None,
) -> Generator[LangfuseSpanHandle, None, None]:
    """Open a best-effort child Langfuse span around the wrapped block.

    Reuses the existing Langfuse/LiteLLM OTEL context: the span becomes the
    current observation for the duration of the block, so any LLM generation
    emitted inside it (via the LiteLLM success callback) nests underneath.

    The span is best-effort. If Langfuse is unavailable, span creation fails, or
    entering/closing the span raises, the block still runs, just untraced.
    Exceptions raised inside the block are never swallowed — they propagate to
    the caller after the span records them on exit.

    Args:
        name: Span name, e.g. ``"llm.main"``.
        metadata: Optional structured metadata (IDs, counts, flags) to attach to
            the span. Do not put raw prompt/response text or PII here — span
            metadata is not redacted. Prompt/response content belongs in
            ``span_input`` and the span output (the Langfuse observation
            input/output fields), consistent with the nested LLM generation.
        span_input: Optional span input value (e.g. prompt messages). May carry
            user content; recorded as the Langfuse observation input, not
            metadata.

    Yields:
        A :class:`LangfuseSpanHandle`; call ``handle.update(output=...)`` inside
        the block to record the span output.
    """
    handle = LangfuseSpanHandle()
    span_context_manager = _start_langfuse_span(
        name=name, metadata=metadata, span_input=span_input
    )
    if span_context_manager is None:
        yield handle
        return

    # Best-effort: if *entering* the span fails, run the wrapped block untraced
    # rather than letting a tracing error abort orchestration.
    try:
        span_context_manager.__enter__()
    except Exception as enter_error:
        structlogger.debug(
            "langfuse_telemetry.langfuse_span.enter_failed",
            error=repr(enter_error),
        )
        yield handle
        return

    exc_info: Tuple[Any, Any, Any] = (None, None, None)
    try:
        yield handle
    except BaseException as block_error:
        # Capture the exception so the span records it on close, then re-raise —
        # the block's exception is never swallowed (incl. asyncio CancelledError).
        exc_info = (type(block_error), block_error, block_error.__traceback__)
        raise
    finally:
        # Closing the span is best-effort too: a close failure must neither mask
        # a block exception nor surface as an orchestration error.
        try:
            span_context_manager.__exit__(*exc_info)
        except Exception as exit_error:
            structlogger.debug(
                "langfuse_telemetry.langfuse_span.exit_failed",
                error=repr(exit_error),
            )


def _start_langfuse_span(
    *,
    name: str,
    metadata: Optional[Dict[str, Any]],
    span_input: Optional[Any],
) -> Optional[Any]:
    """Return a current-span context manager, or None when unavailable.

    Only the span *setup* is guarded so that a failure to create the span
    degrades gracefully, while exceptions raised by the traced block itself
    still propagate (the block runs outside this ``try``).

    Returns:
        The Langfuse ``start_as_current_span`` context manager, or ``None`` if
        Langfuse is not available or the span could not be created.
    """
    if not is_langfuse_configured():
        return None
    try:
        with with_langfuse() as lf:
            if not lf:
                return None
            langfuse_client = lf.get_client()
            kwargs: Dict[str, Any] = {"name": name}
            if span_input is not None:
                kwargs["input"] = span_input
            if metadata is not None:
                kwargs["metadata"] = metadata
            return langfuse_client.start_as_current_span(**kwargs)
    except Exception as e:
        structlogger.debug(
            "langfuse_telemetry.langfuse_span.failed",
            error=repr(e),
        )
        return None
